<?php
$today = date('Y-m-d');
$month_start = date('Y-m-d', strtotime('-29 days'));
$department_name = !empty($department['department']) ? $department['department'] : 'R&D - Design';
$stats = array('total' => count($tasks), 'assigned_today' => 0, 'due_today' => 0, 'overdue' => 0, 'open' => 0, 'completed_month' => 0, 'on_time_month' => 0);
$people = array();
$trend = array();
for ($i = 6; $i >= 0; $i--) {
    $key = date('Y-m-d', strtotime('-' . $i . ' days'));
    $trend[$key] = array('label' => date('d M', strtotime($key)), 'assigned' => 0, 'completed' => 0);
}
foreach ($tasks as &$task) {
    $status = strtoupper((string) $task['status']);
    $created_date = !empty($task['created_on']) ? date('Y-m-d', strtotime($task['created_on'])) : '';
    $due_date = !empty($task['committed_due_date']) && $task['committed_due_date'] !== '0000-00-00' ? date('Y-m-d', strtotime($task['committed_due_date'])) : '';
    $completed_date = !empty($task['completed_on']) && $task['completed_on'] !== '0000-00-00 00:00:00' ? date('Y-m-d', strtotime($task['completed_on'])) : '';
    $is_completed = $status === 'COMPLETED';
    $is_open = !$is_completed;
    $is_late = $is_completed && $due_date !== '' && $completed_date !== '' && $completed_date > $due_date;
    $is_overdue = $is_open && $due_date !== '' && $due_date < $today;
    $delay_days = $is_late ? (int) floor((strtotime($completed_date) - strtotime($due_date)) / 86400) : ($is_overdue ? (int) floor((strtotime($today) - strtotime($due_date)) / 86400) : 0);
    $task['_created_date'] = $created_date;
    $task['_due_date'] = $due_date;
    $task['_completed_date'] = $completed_date;
    $task['_is_open'] = $is_open;
    $task['_is_late'] = $is_late;
    $task['_is_overdue'] = $is_overdue;
    $task['_delay_days'] = $delay_days;
    if ($created_date === $today) $stats['assigned_today']++;
    if ($is_open) $stats['open']++;
    if ($is_open && $due_date === $today) $stats['due_today']++;
    if ($is_overdue) $stats['overdue']++;
    if ($is_completed && $completed_date >= $month_start && $completed_date <= $today) {
        $stats['completed_month']++;
        if ($due_date !== '' && $completed_date <= $due_date) $stats['on_time_month']++;
    }
    if (isset($trend[$created_date])) $trend[$created_date]['assigned']++;
    if (isset($trend[$completed_date])) $trend[$completed_date]['completed']++;
    $uid = (int) $task['assigned_to_user_id'];
    if (!isset($people[$uid])) $people[$uid] = array('user_id' => $uid, 'name' => $task['assignee_name'], 'assigned' => 0, 'completed' => 0, 'ongoing' => 0, 'late' => 0, 'on_time' => 0);
    $people[$uid]['assigned']++;
    if ($is_completed) { $people[$uid]['completed']++; if ($is_late) $people[$uid]['late']++; elseif ($due_date !== '' && $completed_date <= $due_date) $people[$uid]['on_time']++; }
    else $people[$uid]['ongoing']++;
}
unset($task);
foreach ($people as &$person) $person['performance'] = $person['completed'] > 0 ? round(($person['on_time'] / $person['completed']) * 100) : 0;
unset($person);
usort($people, function ($a, $b) { return $b['assigned'] - $a['assigned']; });
$on_time_rate = $stats['completed_month'] > 0 ? round(($stats['on_time_month'] / $stats['completed_month']) * 100) : 0;
function rndSafe($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
function rndDate($value) { return $value !== '' ? date('d M Y', strtotime($value)) : '-'; }
?>
