<script>$(function(){var today='<?php echo $today; ?>',monthStart='<?php echo $month_start; ?>',report='';function esc(v){return $('<div>').text(v==null?'':v).html()}function dateText(v){if(!v)return '-';var p=v.split('-');return p[2]+'-'+p[1]+'-'+p[0]}var table=$('#taskTable').DataTable({pageLength:25,order:[[6,'asc']],scrollX:true,columnDefs:[{targets:0,orderable:false,searchable:false}],language:{emptyTable:'No R&D - Design tasks found',zeroRecords:'No tasks match the selected report'}});$.fn.dataTable.ext.search.push(function(settings,data,index){if(settings.nTable.id!=='taskTable')return true;var r=$(settings.aoData[index].nTr),status=$('#statusFilter').val(),user=$('#userFilter').val(),created=String(r.data('created')||''),due=String(r.data('due')||''),completed=String(r.data('completed')||''),open=String(r.data('open'))==='1';if(user&&String(r.data('user'))!==user)return false;if(status==='OVERDUE'&&String(r.data('overdue'))!=='1')return false;if(status&&status!=='OVERDUE'&&String(r.data('status'))!==status)return false;if(report==='assigned_today'&&created!==today)return false;if(report==='due_today'&&!(open&&due===today))return false;if(report==='overdue'&&String(r.data('overdue'))!=='1')return false;if(report==='open'&&!open)return false;if(report==='completed_month'&&!(String(r.data('status'))==='COMPLETED'&&completed>=monthStart&&completed<=today))return false;if(report==='on_time_month'&&!(String(r.data('status'))==='COMPLETED'&&completed>=monthStart&&completed<=today&&due&&completed<=due))return false;return true});function renumber(){var info=table.page.info();table.rows({page:'current',search:'applied'}).nodes().each(function(row,i){$('td:first',row).text(info.start+i+1)})}table.on('draw',renumber);renumber();$('#taskSearch').on('keyup change',function(){table.search(this.value).draw()});$('#userFilter,#statusFilter').on('change',function(){report='';$('#registerTitle').text('R&D - Design Task Register');table.draw()});$('#reset').on('click',function(){report='';$('#taskSearch,#userFilter,#statusFilter').val('');table.search('').draw();$('#registerTitle').text('R&D - Design Task Register')});$('.kpi-report').on('click',function(){var labels={all:'All R&D - Design Tasks',assigned_today:'Tasks Assigned Today',due_today:'Tasks Due Today',overdue:'Overdue Tasks',open:'Open Tasks',completed_month:'Tasks Completed — Last 30 Days',on_time_month:'On-Time Completions — Last 30 Days'};report=String($(this).data('report'));$('#taskSearch,#userFilter,#statusFilter').val('');table.search('').draw();$('#registerTitle').text(labels[report]);$('html,body').animate({scrollTop:$('#taskRegister').offset().top-80},350)});
var raw=<?php echo json_encode(array_map(function($t){return array('id'=>(int)$t['id'],'code'=>$t['task_code'],'title'=>$t['title'],'user_id'=>(int)$t['assigned_to_user_id'],'user'=>$t['assignee_name'],'priority'=>$t['priority'],'created'=>$t['_created_date'],'due'=>$t['_due_date'],'completed'=>$t['_completed_date'],'status'=>$t['status'],'progress'=>(int)$t['progress_percent'],'late'=>$t['_is_late'],'overdue'=>$t['_is_overdue'],'delay'=>(int)$t['_delay_days']);},$tasks)); ?>;function renderPerformance(){var from=$('#fromDate').val(),to=$('#toDate').val(),map={};if(from&&to&&from>to){alert('From Date cannot be after To Date.');return}$.each(raw,function(_,t){if((from&&t.created<from)||(to&&t.created>to))return;var k=t.user_id;if(!map[k])map[k]={id:k,name:t.user,assigned:0,completed:0,ongoing:0,late:0,onTime:0};map[k].assigned++;if(t.status==='COMPLETED'){map[k].completed++;if(t.late)map[k].late++;else if(t.due&&t.completed<=t.due)map[k].onTime++}else map[k].ongoing++});var rows=Object.keys(map).map(function(k){var p=map[k];p.rate=p.completed?Math.round(p.onTime/p.completed*100):0;return p}).sort(function(a,b){return b.assigned-a.assigned}),html='';$.each(rows,function(_,p){html+='<tr><td><b>'+esc(p.name)+'</b></td><td><button class="metric detail" data-user="'+p.id+'" data-type="assigned">'+p.assigned+'</button></td><td><button class="metric green detail" data-user="'+p.id+'" data-type="completed">'+p.completed+'</button></td><td><button class="metric blue detail" data-user="'+p.id+'" data-type="ongoing">'+p.ongoing+'</button></td><td><button class="metric red detail" data-user="'+p.id+'" data-type="late">'+p.late+'</button></td><td><span class="performance">'+p.rate+'%</span></td></tr>'});$('#performanceBody').html(html||'<tr><td colspan="6" class="empty">No tasks found for this date range.</td></tr>')}$('#applyDates').on('click',renderPerformance);$('#allTime').on('click',function(){$('#fromDate,#toDate').val('');renderPerformance()});$(document).on('click','.detail',function(){var uid=Number($(this).data('user')),type=String($(this).data('type')),from=$('#fromDate').val(),to=$('#toDate').val(),rows=raw.filter(function(t){if(t.user_id!==uid||(from&&t.created<from)||(to&&t.created>to))return false;if(type==='completed')return t.status==='COMPLETED';if(type==='ongoing')return t.status!=='COMPLETED';if(type==='late')return t.late;return true}),html='';$.each(rows,function(i,t){var state=t.late?'Completed late by '+t.delay+' day(s)':(t.overdue?'Overdue by '+t.delay+' day(s)':t.status.replace(/_/g,' '));html+='<tr><td>'+(i+1)+'</td><td><a href="<?php echo page_url; ?>Task_management/view/'+t.id+'"><b>'+esc(t.code)+'</b></a><br>'+esc(t.title)+'</td><td>'+esc(t.priority)+'</td><td>'+dateText(t.created)+'</td><td>'+dateText(t.due)+'</td><td>'+dateText(t.completed)+'</td><td>'+t.progress+'%</td><td>'+esc(state)+'</td></tr>'});$('#detailTitle').text((rows[0]?rows[0].user:'Team')+' — '+type.replace('_',' ')+' ('+rows.length+')');$('#detailBody').html(html||'<tr><td colspan="8" class="empty">No records found.</td></tr>');$('#detailModal').modal('show')});renderPerformance();new Chart(document.getElementById('trendChart').getContext('2d'),{type:'bar',data:{labels:<?php echo json_encode(array_column($trend,'label')); ?>,datasets:[{label:'Assigned',backgroundColor:'rgba(112,72,200,.35)',borderColor:'#7048c8',borderWidth:1,data:<?php echo json_encode(array_column($trend,'assigned')); ?>},{label:'Completed',backgroundColor:'#28b889',data:<?php echo json_encode(array_column($trend,'completed')); ?>}]},options:{maintainAspectRatio:false,responsive:true,legend:{position:'bottom'},scales:{yAxes:[{ticks:{beginAtZero:true,stepSize:1}}]}}})});</script></body></html>
